#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package WolverineFx@4.2.0 #:package WolverineFx.Marten@4.2.0 #:package WolverineFx.RDBMS@4.2.0 #:package WolverineFx.Postgresql@4.2.0 #:package WolverineFx.FluentValidation@4.2.0 #:package WolverineFx.Http@4.2.0 #:package WolverineFx.RabbitMQ@4.2.0 #:package WolverineFx.AzureServiceBus@4.2.0 #:package WolverineFx.Http.FluentValidation@4.2.0 #:package WolverineFx.Http.Marten@4.2.0 #:package WolverineFx.AmazonSqs@4.2.0 #:package WolverineFx.EntityFrameworkCore@4.2.0 #:package WolverineFx.SqlServer@4.2.0 #:package WolverineFx.Kafka@4.2.0 #:package WolverineFx.MemoryPack@4.2.0 #:package WolverineFx.MessagePack@4.2.0 #:package WolverineFx.MQTT@4.2.0 #:package WolverineFx.Pubsub@4.2.0 #:package WolverineFx.Pulsar@4.2.0 #:package WolverineFx.RavenDb@4.2.0 #:package Microsoft.CodeAnalysis.Common@4.14.0 #:package Microsoft.CodeAnalysis.Workspaces.Common@4.14.0 #:package Swashbuckle.AspNetCore@9.0.3 #:package Swashbuckle.AspNetCore.Swagger@9.0.3 #:package Swashbuckle.AspNetCore.SwaggerGen@9.0.3 #:package Swashbuckle.AspNetCore.SwaggerUI@9.0.3 #:property LangVersion=preview #:property TargetFramework=net10.0 #:property Nullable=enable #:property ImplicitUsings=enable #:property GenerateJsonSourceGeneration=true  using Microsoft.AspNetCore.Builder; using Microsoft.Extensions.DependencyInjection; using Wolverine; using Contracts.Messages; //在 Device、UserDevice 表均加上唯一约束 (DeviceId, UserId, CorrelationId)，并在 Handler 中捕获唯一冲突异常后直接返回成功. var builder = WebApplication.CreateBuilder(args); builder.Logging.AddConsole(); // 同样使用默认 InMemoryTransport，或者共用外部 transport builder.Host.UseWolverine(opts => {     // 如果组件 A 与 B 分别在不同进程，而你使用 RabbitMQ：     // opts.UseRabbitMq("amqp://guest:guest@localhost:5672");     // 如果你想把事件持久化到数据库（Outbox），打开下面的配置     // opts.PersistMessagesWithPostgres("Host=...;Database=...;Username=...;Password=...");     // opts.Policies.OnException<DbUpdateException>(e => e.Retry(3));     // opts.DefaultRoutingConvention = new Wolverine.RabbitMq.Routing.RabbitMqRoutingConvention();     // opts.UseRabbitMq(rabbit =>     // {     //     rabbit.ConnectionFactory.Uri = new Uri("amqp://guest:guest@localhost:5672");     //     rabbit.HostName = "localhost";     //     rabbit.Port = 5672;     //     rabbit.Username = "guest";     //     rabbit.Password = "guest";     // })ConfigureDeadLetterQueue("dead-letter");     // 开启 Outbox（即使 InMemory，也可以演示事务）     opts.EnableOutbox();   // 若使用真实DB 记得打开      // 让所有 Handler 自动发现（包括跨程序集）     opts.IncludeAssembly(typeof(IUserDeviceRepository).Assembly); // 自己的      //  Grafana/Prometheus、Jaeger 集成，监控每一步延迟、Saga 成功率.     opts.EnableOpenTelemetry(); });  builder.Services.AddSingleton<IUserDeviceRepository, InMemoryUserDeviceRepository>();  var app = builder.Build();  app.MapGet("/users/{userId}/devices", async (Guid userId, IUserDeviceRepository repo) => {     var devices = await repo.GetDeviceIdsAsync(userId);     return Results.Ok(new UserDevicesResponse(userId, devices)); });  app.MapGet("/device/{deviceId}/users", async (Guid deviceId,     IUserDeviceRepository repo) => {     var userIds = await repo.GetUserIdsAsync(deviceId);     return Results.Ok(new DeviceUsersResponse(deviceId, userIds)); });  app.Run();  public class UserDeviceHandler {     private readonly IUserDeviceRepository _repo;      public UserDeviceHandler(IUserDeviceRepository repo) => _repo = repo;      // 处理设备绑定事件     public async Task Handle(UserDeviceAdded @event)     {         // 业务：把记录写入本地表（可能是 EF、Dapper、Mongo…）         await _repo.AddDeviceAsync(@event.UserId, @event.DeviceId);     }      // 处理设备解绑事件     public async Task Handle(UserDeviceRemoved @event)     {         await _repo.RemoveDeviceAsync(@event.UserId, @event.DeviceId);     }      // 可选：查询请求‑响应（如果想让 B 主动提供查询而不是直接 HTTP）     public async Task<UserDevicesResponse> Handle(GetUserDevices request)     {         var ids = await _repo.GetDeviceIdsAsync(request.UserId);         return new UserDevicesResponse(request.UserId, ids);     } }  public interface IUserDeviceRepository {     Task AddAsync(Guid userId, Guid deviceId);     Task RemoveAsync(Guid userId, Guid deviceId);     Task<IReadOnlyList<Guid>> GetDeviceIdsAsync(Guid userId);     Task<IReadOnlyList<Guid>> GetUserIdsAsync(Guid deviceId); }  // 简单的内存实现（演示，生产环境请换成数据库） public class InMemoryUserDeviceRepository : IUserDeviceRepository {     // 两个方向的索引，方便查询     private readonly ConcurrentDictionary<Guid, ConcurrentBag<Guid>> _byUser = new();     private readonly ConcurrentDictionary<Guid, ConcurrentBag<Guid>> _byDevice = new();      public Task AddAsync(Guid userId, Guid deviceId)     {         _byUser.GetOrAdd(userId, _ => new ConcurrentBag<Guid>()).Add(deviceId);         _byDevice.GetOrAdd(deviceId, _ => new ConcurrentBag<Guid>()).Add(userId);         return Task.CompletedTask;     }      public Task RemoveAsync(Guid userId, Guid deviceId)     {         if (_byUser.TryGetValue(userId, out var bagU))         {             var remaining = bagU.Where(id => id != deviceId).ToArray();             _byUser[userId] = new ConcurrentBag<Guid>(remaining);         }         if (_byDevice.TryGetValue(deviceId, out var bagD))         {             var remaining = bagD.Where(id => id != userId).ToArray();             _byDevice[deviceId] = new ConcurrentBag<Guid>(remaining);         }         return Task.CompletedTask;     }      public Task<IReadOnlyList<Guid>> GetDeviceIdsAsync(Guid userId) =>         Task.FromResult((IReadOnlyList<Guid>)_byUser.GetOrAdd(userId, _ => new ConcurrentBag<Guid>()).ToArray());      public Task<IReadOnlyList<Guid>> GetUserIdsAsync(Guid deviceId) =>         Task.FromResult((IReadOnlyList<Guid>)_byDevice.GetOrAdd(deviceId, _ => new ConcurrentBag<Guid>()).ToArray()); }  public class UserDeviceHandler {     private readonly IUserDeviceRepository _repo;     private readonly ILogger<UserDeviceHandler> _log;     public UserDeviceHandler(IUserDeviceRepository repo, ILogger<UserDeviceHandler> log)     {         _repo = repo;         _log = log;     }      // 绑定事件 —— 持久化关联     public async Task Handle(DeviceBoundToUser @event)     {         _log.LogInformation("绑定: Device {DeviceId} → User {UserId}", @event.DeviceId, @event.UserId);         await _repo.AddAsync(@event.UserId, @event.DeviceId);     }      // 解绑事件 —— 删除关联     public async Task Handle(DeviceUnboundFromUser @event)     {         _log.LogInformation("解绑: Device {DeviceId} ← User {UserId}", @event.DeviceId, @event.UserId);         await _repo.RemoveAsync(@event.UserId, @event.DeviceId);     }      // 可选：如果你想把 **查询** 也走消息总线（例如 B 作为查询服务），可以实现 Request‑Response     public async Task<UserDevicesResponse> Handle(QueryUserDevices query)     {         var ids = await _repo.GetDeviceIdsAsync(query.UserId);         return new UserDevicesResponse(query.UserId, ids);     }      public async Task<DeviceUsersResponse> Handle(QueryDeviceUsers query)     {         var ids = await _repo.GetUserIdsAsync(query.DeviceId);         return new DeviceUsersResponse(query.DeviceId, ids);     } }  // 补偿处理. public class UserDeviceCompensationHandler {     private readonly IUserDeviceRepository _repo;     public UserDeviceCompensationHandler(IUserDeviceRepository repo) => _repo = repo;      // 补偿（删除关联记录）     public async Task Handle(CompensateUserDevice cmd)     {         // 这里使用 CorrelationId 做幂等保护（若已经删除则忽略）.必须在实现层（EF、Dapper）里加入唯一键/事务保证 幂等         await _repo.RemoveAsync(cmd.UserId, cmd.DeviceId);     } } 
